QString localizedSiteError(const QString &error,bool english){if(english)return error;if(error.startsWith("OSM source unavailable (HTTP ")){const auto status=error.section("HTTP ",1).section(')',0,0);return QString::fromUtf8("Nguồn OSM chưa khả dụng (HTTP %1). Dự án trước đó vẫn được giữ.").arg(status);}const QMap<QString,QString> messages={{"OSM connection unavailable. Previous projects are retained.","Không kết nối được nguồn OSM. Dự án trước đó vẫn được giữ."},{"Combined geometry exceeds eight million points","Hình học sau khi ghép vượt giới hạn tám triệu điểm."},{"Wait two seconds before another OSM request","Đợi ít nhất hai giây trước khi gửi yêu cầu OSM tiếp theo."},{"OSM providers are unavailable; previous projects are retained","Các máy chủ OSM chưa khả dụng; dự án trước đó vẫn được giữ."},{"OSM response exceeds 35 MB; choose a smaller extent","Phản hồi OSM vượt 35 MB; hãy chọn phạm vi nhỏ hơn."},{"Invalid OSM JSON response","Nguồn OSM trả JSON không hợp lệ."},{"Unknown OSM detail profile","Nhóm dữ liệu OSM không được hỗ trợ."},{"This source window crosses the supported geographic boundary","Cửa sổ nguồn vượt giới hạn tọa độ được hỗ trợ."},{"Too many geometry parts after enrichment","Quá nhiều phần hình học sau khi bổ sung dữ liệu."},{"OSM enrichment has a different site boundary","Nguồn bổ sung OSM có ranh khu đất khác."},{"At least three boundary vertices are required","Ranh cần ít nhất ba đỉnh khác nhau."},{"Boundary exceeds 4096 vertices","Ranh vượt quá 4.096 đỉnh."},{"Invalid boundary coordinate","Có tọa độ đỉnh không hợp lệ."},{"Boundary has duplicate adjacent vertices","Có hai đỉnh liền nhau bị trùng."},{"Boundary crosses or touches itself","Các cạnh ranh tự cắt hoặc chạm nhau."},{"Boundary area must be at least one square metre","Diện tích ranh phải từ 1 m² trở lên."},{"Invalid site coordinate or extent","Tọa độ hoặc kích thước khu đất không hợp lệ."},{"Unknown site shape","Loại ranh khu đất không được hỗ trợ."},{"Site exceeds the 3000 m selection extent","Đường kính hoặc cạnh vùng chọn không vượt quá 3.000 m."},{"Invalid geographic boundary coordinate","Tọa độ ranh phải là kinh độ, vĩ độ WGS84 hợp lệ."},{"The selected site is outside this source window","Vùng chọn nằm ngoài cửa sổ dữ liệu của nguồn."},{"No source geometry intersects the selected boundary","Không có đối tượng nguồn giao với ranh vùng chọn."},{"Too many geometry parts after clipping","Hình học sau cắt quá lớn. Hãy chia nhỏ khu đất."},{"No supported OSM geometry was found in this area","Chưa có hình học OSM được hỗ trợ trong vùng chọn."},{"The OSM server returned incomplete data","Máy chủ OSM trả về dữ liệu chưa đầy đủ."}};return messages.value(error,error);}
namespace {
constexpr double epsilon=1e-7;
double cross(QPointF a,QPointF b){return a.x()*b.y()-a.y()*b.x();}
double dot(QPointF a,QPointF b){return a.x()*b.x()+a.y()*b.y();}
bool onEdge(QPointF p,QPointF a,QPointF b){const auto d=b-a;return std::abs(cross(p-a,d))<=epsilon*std::max(1.,std::hypot(d.x(),d.y()))&&dot(p-a,p-b)<=epsilon;}
bool intersect(QPointF a,QPointF b,QPointF c,QPointF d){const double abC=cross(b-a,c-a),abD=cross(b-a,d-a),cdA=cross(d-c,a-c),cdB=cross(d-c,b-c);if(((abC>epsilon&&abD<-epsilon)||(abC<-epsilon&&abD>epsilon))&&((cdA>epsilon&&cdB<-epsilon)||(cdA<-epsilon&&cdB>epsilon)))return true;return onEdge(c,a,b)||onEdge(d,a,b)||onEdge(a,c,d)||onEdge(b,c,d);}
QPainterPath path(const QPolygonF &ring){QPainterPath p;p.setFillRule(Qt::OddEvenFill);p.addPolygon(ring);p.closeSubpath();return p;}
double filledArea(const QPainterPath &p){double sum=0;for(const auto &ring:p.toFillPolygons())sum+=std::abs(ringArea(ring));return sum;}
}
QPolygonF primitiveBoundary(const Site &site){if(site.shape=="circle")return circleBoundary(site.radius);if(site.shape=="polygon")return site.boundary;const double w=site.shape=="square"?site.radius*2:site.width,h=site.shape=="square"?site.radius*2:site.height;QPolygonF ring{{-w/2,-h/2},{w/2,-h/2},{w/2,h/2},{-w/2,h/2}};const double a=site.rotation*M_PI/180,c=std::cos(a),s=std::sin(a);for(auto &p:ring)p={p.x()*c-p.y()*s,p.x()*s+p.y()*c};return ring;}
QString boundaryError(const QPolygonF &input){QPolygonF ring=input;if(ring.size()>1&&ring.first()==ring.last())ring.removeLast();if(ring.size()<3)return "At least three boundary vertices are required";if(ring.size()>4096)return "Boundary exceeds 4096 vertices";for(int i=0;i<ring.size();++i){const auto a=ring[i],b=ring[(i+1)%ring.size()];if(!std::isfinite(a.x())||!std::isfinite(a.y())||std::abs(a.x())>200000||std::abs(a.y())>200000)return "Invalid boundary coordinate";if(std::hypot(b.x()-a.x(),b.y()-a.y())<.001)return "Boundary has duplicate adjacent vertices";for(int j=i+1;j<ring.size();++j){if(j==i+1||(i==0&&j==ring.size()-1))continue;if(intersect(a,b,ring[j],ring[(j+1)%ring.size()]))return "Boundary crosses or touches itself";}}if(std::abs(ringArea(ring))<1)return "Boundary area must be at least one square metre";return{};}
QString selectionError(const Site &site,double maximum){if(!std::isfinite(site.lat)||!std::isfinite(site.lon)||std::abs(site.lat)>85||std::abs(site.lon)>180||!std::isfinite(site.radius)||site.radius<=0)return "Invalid site coordinate or extent";if(!QSet<QString>{"circle","square","rectangle","polygon"}.contains(site.shape))return "Unknown site shape";if(site.radius>maximum+.001)return "Site exceeds the 3000 m selection extent";const auto ring=site.boundary.isEmpty()?primitiveBoundary(site):site.boundary;const auto error=boundaryError(ring);if(!error.isEmpty())return error;if(envelopeRadius(site)>maximum*std::sqrt(2.)+.001)return "Site exceeds the 3000 m selection extent";const auto b=ring.boundingRect();if(std::max(b.width(),b.height())>maximum*2+.001&&site.rotation==0)return "Site exceeds the 3000 m selection extent";return{};}
double envelopeRadius(const Site &site){double r=0;for(const auto &p:site.boundary.isEmpty()?primitiveBoundary(site):site.boundary)r=std::max(r,std::hypot(p.x(),p.y()));return std::max(1.,r);}
bool boundaryContains(const QPolygonF &ring,const QPointF &point){if(ring.containsPoint(point,Qt::OddEvenFill))return true;for(int i=0;i<ring.size();++i)if(onEdge(point,ring[i],ring[(i+1)%ring.size()]))return true;return false;}
Site siteFromGeographicBoundary(const QPolygonF &points,const QString &name){if(points.size()<3)throw std::runtime_error("At least three boundary vertices are required");for(const auto &p:points)if(!std::isfinite(p.x())||!std::isfinite(p.y())||std::abs(p.x())>180||std::abs(p.y())>85)throw std::runtime_error("Invalid geographic boundary coordinate");Site site;site.shape="polygon";if(!name.isEmpty())site.name=name;const auto bounds=points.boundingRect();site.lon=bounds.center().x();site.lat=bounds.center().y();for(const auto &p:points)site.boundary.append(localPoint(p.x(),p.y(),site));if(site.boundary.first()==site.boundary.last())site.boundary.removeLast();const auto error=boundaryError(site.boundary);if(!error.isEmpty())throw std::runtime_error(error.toUtf8().constData());const auto local=site.boundary.boundingRect();site.radius=std::max(local.width(),local.height())/2;site.width=local.width();site.height=local.height();return site;}
Project reclipProject(const Project &source,const Site &selection,const std::atomic_bool *cancel){
 if(cancel&&cancel->load())throw std::runtime_error("Canceled");
 const auto error=selectionError(selection,100000);if(!error.isEmpty())throw std::runtime_error(error.toUtf8().constData());
 Project p;p.site=selection;if(p.site.boundary.isEmpty())p.site.boundary=primitiveBoundary(p.site);p.style=source.style;p.layerState=source.layerState;p.notes=source.notes;p.view=source.view;p.imports=source.imports;
 QPolygonF sourceBoundary;for(const auto &point:source.site.boundary.isEmpty()?primitiveBoundary(source.site):source.site.boundary){const auto ll=geographicPoint(point,source.site);sourceBoundary.append(localPoint(ll.x(),ll.y(),p.site));}
 const double area=std::abs(ringArea(p.site.boundary)),covered=filledArea(path(sourceBoundary).intersected(path(p.site.boundary)));if(covered<.001&&source.imports.isEmpty())throw std::runtime_error("The selected site is outside this source window");
 for(auto f:source.features){if(cancel&&cancel->load())throw std::runtime_error("Canceled");if(!f.importId.isEmpty())continue;for(auto &ring:f.rings)for(auto &point:ring){const auto ll=geographicPoint(point,source.site);point=localPoint(ll.x(),ll.y(),p.site);}p.features.append(clipToSite(f,p.site));if(p.features.size()>Project::maximumGeometryParts)throw std::runtime_error("Too many geometry parts after clipping");}
 reclipGeoJsonOverlays(p,cancel);if(p.features.isEmpty())throw std::runtime_error("No source geometry intersects the selected boundary");p.source=source.source;p.source["selection_clipped_at"]=QDateTime::currentDateTimeUtc().toString(Qt::ISODate);p.source["coverage_fraction"]=std::clamp(covered/area,0.,1.);p.source["coverage_complete"]=covered/area>=.99999;p.source["parent_extent"]=QJsonObject{{"name",source.site.name},{"lat",source.site.lat},{"lon",source.site.lon},{"radius",source.site.radius},{"shape",source.site.shape}};p.source["coverage_note"]="Reclipped from the retained primary source window. coverage_fraction describes geometric primary-window coverage, not real-world data completeness. User overlays do not increase primary source coverage.";return p;
}
